mapper.select:

WITH RECURSIVE visible_nodes AS (
    SELECT c.id, c.parent_id FROM kb_document_category c
    WHERE c.space_id = #{spaceId} AND EXISTS (
        SELECT 1 FROM kb_document d WHERE d.space_id = c.space_id AND d.category_id = c.id
        AND d.status NOT IN ('deleted', 'archived') AND d.security_level <= #{clearance}
        AND 
        AND 
    )
    UNION
    SELECT p.id, p.parent_id FROM kb_document_category p JOIN visible_nodes n ON p.id = n.parent_id
    WHERE p.space_id = #{spaceId}
)
SELECT c.id, c.space_id, c.parent_id, c.name, c.normalized_name, c.sort_order, c.created_at, c.updated_at
FROM kb_document_category c WHERE c.space_id = #{spaceId} AND c.id IN (SELECT id FROM visible_nodes)

    AND c.parent_id = #{parentId}
    AND c.parent_id IS NULL

AND (c.sort_order, c.id) > (#{afterOrder}, #{afterId})
ORDER BY c.sort_order, c.id LIMIT #{limit}

SELECT id, space_id, parent_id, name, normalized_name, sort_order, created_at, updated_at
FROM kb_document_category WHERE space_id = #{spaceId}

    AND parent_id = #{parentId}
    AND parent_id IS NULL

AND (sort_order, id) > (#{afterOrder}, #{afterId})
ORDER BY sort_order, id LIMIT #{limit}
